29	import type { SessionContext } from "eve/context";
30	
31	export interface TenantCaller {
32	  tenantId: string;
33	  userId: string;
34	}
35	
36	export function requireTenantCaller(ctx: SessionContext): TenantCaller {
37	  const caller = ctx.session.auth.current;
38	  const tenantId = caller?.attributes.tenantId;
39	
40	  if (caller?.principalType !== "user" || typeof tenantId !== "string") {
41	    throw new Error("An authenticated tenant user is required.");
42	  }
43	
44	  return { tenantId, userId: caller.principalId };
45	}
