55	import { defineDynamic, defineInstructions } from "eve/instructions";
56	import { memoryStore } from "../lib/memory-store";
57	import { requireTenantCaller } from "../lib/tenant";
58	
59	export default defineDynamic({
60	  events: {
61	    "turn.started": async (_event, ctx) => {
62	      const scope = requireTenantCaller(ctx);
63	      const memories = await memoryStore.list(scope, { limit: 50 });
