148	
149	```ts title="agent/lib/memory-store.ts"
150	export interface MemoryScope {
151	  tenantId: string;
152	  userId: string;
153	}
154	
155	export interface Memory {
156	  key: string;
157	  value: string;
158	  updatedAt: string;
159	}
160	
