162	  list(scope: MemoryScope, options: { limit: number }): Promise<Memory[]>;
163	  put(scope: MemoryScope, memory: { key: string; value: string }): Promise<Memory>;
164	  delete(scope: MemoryScope, key: string): Promise<boolean>;
165	}
