9	export interface ErasureReport {
10	  /** Derived caches dropped wholesale; they rebuild lazily on next refresh. */
11	  dossiersDeleted: number;
12	  factsDeleted: number;
13	  /** Audio and attachment blobs whose source no longer backs any fact. */
14	  orphanedBlobUrls: string[];
