21	const WHITESPACE_REGEX = /\s+/;
22	
23	const escapeRegex = (value: string) =>
24	  value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
25	
26	// Word-ish boundaries that understand umlauts: JS \b is ASCII-only, so
27	// \bÖzdemir would never match after a space. Lookarounds on Unicode letters/
28	// digits give real token edges; the optional s covers the German genitive
29	// ("Petras Termin").
30	const tokenAlternative = (token: string) =>
31	  String.raw`(?<![\p{L}\p{N}_])${escapeRegex(token)}s?(?![\p{L}\p{N}_])`;
32	
33	interface Redactor {
34	  // Case-insensitive candidate probe — plain substrings only, because MongoDB
35	  // $regex accepts neither the g nor the u flag. Over-matching is fine: the
36	  // precise pattern decides what actually changes.
37	  probe: RegExp;
38	  redact: (value: string) => string;
39	}
40	
41	// Identifiers: the full name and emails as exact substrings, plus each name
42	// token (≥3 chars, word-bounded) so first-name-only mentions in transcripts
43	// are erased too. Over-redaction is the GDPR-safe direction.
44	const buildRedactor = (person: Person): Redactor | null => {
45	  const exact = [person.name, ...person.emails].filter(
46	    (identifier) => identifier.length > 2
47	  );
48	  const tokens = person.name
49	    .split(WHITESPACE_REGEX)
50	    .filter((token) => token.length > 2);
51	  if (exact.length === 0 && tokens.length === 0) {
52	    return null;
53	  }
54	  const pattern = new RegExp(
55	    [...exact.map(escapeRegex), ...tokens.map(tokenAlternative)].join("|"),
56	    "giu"
57	  );
58	  return {
59	    probe: new RegExp([...exact, ...tokens].map(escapeRegex).join("|"), "i"),
60	    redact: (value) => value.replace(pattern, REDACTED),
61	  };
62	};
