112	// Redact string values (and string-array items) in an entity draft's loose
113	// data record. Returns the original reference when nothing changed.
114	const redactRecord = (
115	  data: Record<string, unknown>,
116	  redact: (value: string) => string
117	): Record<string, unknown> => {
118	  let changed = false;
119	  const next: Record<string, unknown> = {};
120	  for (const [key, value] of Object.entries(data)) {
121	    if (typeof value === "string") {
122	      const redactedValue = redact(value);
123	      changed ||= redactedValue !== value;
124	      next[key] = redactedValue;
125	    } else if (Array.isArray(value)) {
126	      const redactedItems = value.map((item) =>
127	        typeof item === "string" ? redact(item) : item
128	      );
129	      changed ||= redactedItems.some((item, index) => item !== value[index]);
130	      next[key] = redactedItems;
131	    } else {
132	      next[key] = value;
133	    }
134	  }
135	  return changed ? next : data;
136	};
