252	export const erasePerson = async (
253	  db: Db,
254	  tenantId: string,
255	  personId: ObjectId
256	): Promise<ErasureReport> => {
257	  const { people, facts, sources, proposals, dossiers } = getCollections(db);
258	
259	  const person = await people.findOne({ _id: personId, tenantId });
260	  if (!person) {
261	    return {
262	      dossiersDeleted: 0,
263	      factsDeleted: 0,
264	      orphanedBlobUrls: [],
265	      personDeleted: false,
266	      proposalsRedacted: 0,
267	      redactionSkipped: false,
268	      sourcesRedacted: 0,
