272	  // 1. Delete every fact anchored to the person; remember affected sources.
273	  const personFactFilter = { "anchors.personId": personId, tenantId };
274	  const affectedSourceIds = await facts.distinct("sourceId", personFactFilter);
275	  const { deletedCount: factsDeleted } =
276	    await facts.deleteMany(personFactFilter);
277	
278	  // 2. Discard pending fact drafts about the person in open proposals.
279	  //    Already-reviewed drafts keep their status: the audit trail records
280	  //    what the reviewer decided, not what erasure wishes they had.
281	  await proposals.updateMany(
282	    { status: "open", tenantId },
283	    { $set: { "factDrafts.$[draft].resolution.status": "discarded" } },
284	    {
285	      arrayFilters: [
