288	          "draft.resolution.status": "pending",
289	        },
290	      ],
291	    }
292	  );
293	
294	  // 3. Redact the person's identifiers wherever they appear: source texts and
295	  //    the proposal audit trail. Redaction, not deletion — a source or
296	  //    proposal may cover other entities too.
297	  const redactor = buildRedactor(person);
298	  let sourcesRedacted = 0;
