32	  config: GatewayConfig = {}
33	): ((prompt: string) => Promise<string>) => {
34	  const apiKey = config.apiKey ?? process.env.AI_GATEWAY_API_KEY;
35	  if (!apiKey) {
36	    throw new Error(
37	      "AI_GATEWAY_API_KEY is required (pass config.apiKey or set the env var)"
38	    );
39	  }
40	  const baseUrl = config.baseUrl ?? DEFAULT_BASE_URL;
41	  const maxOutputTokens = config.maxOutputTokens ?? DEFAULT_MAX_OUTPUT_TOKENS;
42	  const model = config.model ?? process.env.EXTRACTION_MODEL ?? DEFAULT_MODEL;
43	  const reasoningEffort =
44	    config.reasoningEffort === undefined
45	      ? DEFAULT_REASONING_EFFORT
46	      : config.reasoningEffort;
47	
48	  return async (prompt: string): Promise<string> => {
49	    const res = await fetch(`${baseUrl}/chat/completions`, {
50	      body: JSON.stringify({
51	        max_tokens: maxOutputTokens,
52	        messages: [{ content: prompt, role: "user" }],
53	        model,
54	        ...(reasoningEffort === null
55	          ? {}
56	          : { reasoning_effort: reasoningEffort }),
57	      }),
58	      headers: {
59	        authorization: `Bearer ${apiKey}`,
60	        "content-type": "application/json",
61	      },
62	      method: "POST",
63	    });
64	    if (!res.ok) {
65	      const body = await res.text();
66	      throw new Error(`gateway ${res.status}: ${body.slice(0, 500)}`);
67	    }
68	    const data = (await res.json()) as {
69	      choices?: { message?: { content?: string } }[];
70	    };
71	    const content = data.choices?.[0]?.message?.content;
72	    if (!content) {
73	      throw new Error("gateway returned no content");
74	    }
75	    return content;
76	  };
