// Upstream assumes every citation is a URL and calls new URL(...).hostname
// directly, which throws and takes the whole message render down with it. Not
// every source is a web page — a citation into a knowledge base is a record
// reference — so fall back to showing the label as given.
const sourceLabel = (source: string): string => {
  try {
    return new URL(source).hostname;
  } catch {
    return source;
  }
};

